import { useId, useRef, useState, type FormEvent } from "react";
import { Button, Card, Checkbox, Flex, FormField, Heading, Image, Input, Text } from "@paraxe/react";
import { defaultLoginLabels, type Login01Props } from "../shared/types";
import "../shared/login.css";
export function Login01({ labels: providedLabels, title = "Welcome back", description = "Sign in to your account.", brandName = "Paraxe", homeHref = "/", logoSrc, forgotPasswordHref = "/forgot-password", signUpHref = "/sign-up", authenticate, unavailableMessage = "Sign-in is unavailable in this preview.", failureMessage = "We couldn't sign you in. Please try again.", successMessage = "Sign-in completed." }: Login01Props) {
  const labels = { ...defaultLoginLabels, ...providedLabels };
  const id = `login-${useId().replace(/:/g, '')}`;
  const [email, setEmail] = useState(''), [password, setPassword] = useState(''), [remember, setRemember] = useState(false), [showPassword, setShowPassword] = useState(false), [pending, setPending] = useState(false), [error, setError] = useState(''), [success, setSuccess] = useState('');
  const submitting = useRef(false);
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (submitting.current || !authenticate) return;
    if (!email.trim() || !password) { setError(labels.incomplete); return; }
    submitting.current = true; setPending(true); setError(''); setSuccess('');
    try { await authenticate({ email: email.trim(), password, remember }); setPassword(''); setSuccess(successMessage); }
    catch { setError(failureMessage); }
    finally { submitting.current = false; setPending(false); }
  }
  return <section className="login01"><Card className="login01-card"><Flex className="login01-content" direction="column">
    <a className="login01-brand" href={homeHref}>{logoSrc ? <Image src={logoSrc} alt="" fit="contain" /> : <span className="login01-mark" aria-hidden="true">P.</span>}{brandName}</a>
    <Flex direction="column" className="login01-intro" size="small"><Heading level="h1">{title}</Heading><Text tone="muted">{description}</Text></Flex>
    <form aria-label={title} aria-busy={pending || undefined} onSubmit={submit}><Flex direction="column" className="login01-fields">
      <FormField id={`${id}-email`} label={labels.email} required><Input id={`${id}-email`} modelValue={email} onModelValueChange={setEmail} name="email" type="email" autocomplete="username" required disabled={pending} invalid={!!error} describedBy={error ? `${id}-error` : undefined} /></FormField>
      <FormField id={`${id}-password`} label={labels.password} required><Input id={`${id}-password`} modelValue={password} onModelValueChange={setPassword} name="password" type={showPassword ? 'text' : 'password'} autocomplete="current-password" required disabled={pending} invalid={!!error} describedBy={error ? `${id}-error` : undefined} /></FormField>
      <Flex justify="between" align="center" wrap><Checkbox modelValue={remember} onModelValueChange={setRemember} disabled={pending}>{labels.remember}</Checkbox><Button variant="text" size="small" aria-controls={`${id}-password`} aria-pressed={showPassword} disabled={pending} onActivate={() => setShowPassword(!showPassword)}>{showPassword ? labels.hidePassword : labels.showPassword}</Button></Flex>
      {error && <p id={`${id}-error`} className="login01-error" role="alert">{error}</p>}{success && <p role="status">{success}</p>}
      {!authenticate && <Text className="login01-notice" tone="muted">{unavailableMessage}</Text>}
      <Button type="submit" width="full" loading={pending} disabled={!authenticate}>{pending ? labels.pending : labels.submit}</Button>
    </Flex></form>
    <Flex className="login01-links" justify="between" wrap><a href={forgotPasswordHref}>{labels.forgotPassword}</a><a href={signUpHref}>{labels.signUp}</a></Flex>
  </Flex></Card></section>;
}

.login01 { padding: var(--space-10) var(--space-4); color: var(--text-primary); font-family: var(--font-family-body); }
.login01 *, .login01 *::before, .login01 *::after { box-sizing: border-box; }
.login01 p, .login01 h1 { margin: 0; }
.login01 .login01-card { max-width: calc(var(--grid-min) * 1.75); margin-inline: auto; }
.login01 .login01-content { gap: var(--stack-gap-lg); }
.login01-brand { display: inline-flex; align-items: center; align-self: flex-start; gap: var(--inline-gap-sm); color: inherit; font-weight: var(--font-weight-bold); text-decoration: none; }
.login01-mark { display: grid; place-items: center; width: calc(var(--space-4) * 2); height: calc(var(--space-4) * 2); border: var(--border-width-thin) solid var(--border-default); border-radius: var(--form-radius); }
.login01-brand .media { width: calc(var(--space-4) * 2); height: calc(var(--space-4) * 2); }
.login01 .login01-intro h1 { font-size: var(--font-size-3xl); line-height: var(--line-height-tight); letter-spacing: var(--letter-spacing-tighter); }
.login01-intro p, .login01-notice { font-size: var(--font-size-sm); line-height: var(--line-height-relaxed); }
.login01 .login01-fields { gap: var(--form-field-gap); }
.login01-links { font-size: var(--typography-caption-size); }
.login01 .btn-text { padding-inline: 0; }
.login01-links a { display: inline-flex; align-items: center; min-height: calc(var(--space-4) * 2.75); color: var(--text-secondary); text-underline-offset: var(--space-1); }
.login01-error { color: var(--color-danger); font-size: var(--font-size-sm); }
.login01 a:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring-color); outline-offset: var(--focus-ring-offset); }

export interface LoginCredentials { email: string; password: string; remember: boolean; }
export interface Login01Labels {
  email: string; password: string; remember: string; showPassword: string; hidePassword: string;
  submit: string; pending: string; forgotPassword: string; signUp: string; incomplete: string;
}
export const defaultLoginLabels: Login01Labels = {
  email: "Email", password: "Password", remember: "Remember me", showPassword: "Show password", hidePassword: "Hide password",
  submit: "Sign in", pending: "Signing in…", forgotPassword: "Forgot password?", signUp: "Create an account", incomplete: "Enter your email and password.",
};
export interface Login01Props {
  labels?: Partial<Login01Labels>;
  title?: string;
  description?: string;
  brandName?: string;
  homeHref?: string;
  logoSrc?: string;
  forgotPasswordHref?: string;
  signUpHref?: string;
  authenticate?: (credentials: LoginCredentials) => Promise<void> | void;
  unavailableMessage?: string;
  failureMessage?: string;
  successMessage?: string;
}
